pub(crate) fn sv_cnf_clause(lits: &[i64]) -> Option<Vec<u32>> {
    let mut out: Vec<u32> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    for l in lits.iter() {
        let l = nikaia_std::num::value(l);
        if l == -1 { return None; }
        if l >= 0 { out.push(u32::try_from(l).unwrap_or_else(|_| panic!("the value does not fit in an `u32`"))); }
    }
    out.sort();
    let mut kept: Vec<u32> = vec![];
    for l in out.iter() {
        let l = nikaia_std::num::value(l);
        let n = kept.len() as i64;
        if n > 0 && *unsafe { nikaia_std::proven::read(&kept, (nikaia_std::proven::sub::<i64>(n, 1)) as usize) } == l { continue; }
        if n > 0 && *unsafe { nikaia_std::proven::read(&kept, (nikaia_std::proven::sub::<i64>(n, 1)) as usize) } == l ^ 1u32 { return None; }
        kept.push(l);
    }
    Some(kept)
}

